['Soup Pot Staples','Egusi, ogbono and everything for a proper pot of soup',1,['Egusi (Ground Melon Seeds)','Ogbono (Ground)','Red Palm Oil','Ground Crayfish','Stockfish Pieces','Iru (Locust Beans)','Goat Meat (Cut)','Spinach (Efo Tete)']],
['Beauty & Hair Favourites','Bundles, braids, shea and hair care customers love',2,['Brazilian Straight Bundle','13x4 Lace Frontal','Xpression Braiding Hair','Raw Shea Butter (Ghana)','Jamaican Black Castor Oil','Edge Control','Satin Bonnet','Mielle Rosemary Mint Hair Oil']],
['Snacks and Sips','Chin chin, plantain chips and your favourite drinks',0,['Chin Chin','Plantain Chips','Roasted Groundnuts','Kuli Kuli','Malta Guinness','Zobo (Hibiscus) Drink','Chivita Orange Juice','Coconut Water']]];
function setitems($db,$cid,$names){$db->prepare('DELETE FROM collection_items WHERE collection_id=?')->execute([$cid]);$miss=[];$i=0;foreach($names as $n){$n=trim($n);if($n==='')continue;$p=$db->prepare('SELECT id FROM products WHERE name=? OR sku=? LIMIT 1');$p->execute([$n,$n]);if($pid=$p->fetchColumn())$db->prepare('INSERT INTO collection_items(collection_id,product_id,sort) VALUES(?,?,?)')->execute([$cid,$pid,$i++]);else $miss[]=$n;}return $miss;}
function newc($db,$t,$sub,$col,$sort,$act){$sl=slug($t);try{$db->prepare('INSERT INTO collections(title,slug,subtitle,color,sort,active) VALUES(?,?,?,?,?,?)')->execute([$t,$sl,$sub,$col,$sort,$act]);}catch(Exception $x){$db->prepare('INSERT INTO collections(title,slug,subtitle,color,sort,active) VALUES(?,?,?,?,?,?)')->execute([$t,$sl.'-'.rand(100,999),$sub,$col,$sort,$act]);}return $db->lastInsertId();}
if($_SERVER['REQUEST_METHOD']==='POST'){$d=$_POST;$q='ok=1';
 if(isset($d['seed'])){if(!$db->query('SELECT COUNT(*) FROM collections')->fetchColumn()){foreach($SETS as $i=>$s){$cid=newc($db,$s[0],$s[1],$s[2],$i,1);setitems($db,$cid,$s[3]);}
  $F=['Ripe Plantain','White Yam (Puna)','Long Grain Parboiled Rice','Egusi (Ground Melon Seeds)','Red Palm Oil','Jamaican Black Castor Oil','Raw Shea Butter (Ghana)','Brazilian Straight Bundle','Indomie Instant Noodles','Malta Guinness','Chin Chin','Goat Meat (Cut)'];$db->prepare('UPDATE products SET featured=1 WHERE name IN('.implode(',',array_fill(0,count($F),'?')).')')->execute($F);}}
 elseif(isset($d['del'])){$db->prepare('DELETE FROM collections WHERE id=?')->execute([(int)$d['id']]);}
 elseif(trim($d['title'])!==''){$id=(int)$d['id'];$act=isset($d['active'])?1:0;if($id)$db->prepare('UPDATE collections SET title=?,subtitle=?,color=?,sort=?,active=? WHERE id=?')->execute([trim($d['title']),trim($d['subtitle']),(int)$d['color']%3,(int)$d['sort'],$act,$id]);else $id=newc($db,trim($d['title']),trim($d['subtitle']),(int)$d['color']%3,(int)$d['sort'],$act);
  $m=setitems($db,$id,preg_split('/\r?\n/',$d['items']));if($m)$q.='&miss='.urlencode(implode(', ',$m));}
 header('Location: collections.php?'.$q);exit;}
if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$db->prepare('SELECT * FROM collections WHERE id=?');$s->execute([$id]);$c=$s->fetch()?:['id'=>0,'title'=>'','subtitle'=>'','color'=>0,'sort'=>0,'active'=>1];$ln=[];
 if($c['id'])foreach($db->query('SELECT p.name FROM collection_items i JOIN products p ON p.id=i.product_id WHERE i.collection_id='.(int)$c['id'].' ORDER BY i.sort') as $x)$ln[]=$x['name'];
 ahead($c['id']?'Edit collection':'Add collection','collections.php');?><form method="post" class="fm"><?=csrf()?><input type="hidden" name="id" value="<?=$c['id']?>"><label>Title<input name="title" required value="<?=e($c['title'])?>"></label><label>Short description<input name="subtitle" value="<?=e($c['subtitle'])?>"></label>
 <div class="g3"><label>Colour<select name="color"><?php foreach(['Purple','Green','Gold'] as $i=>$n)echo '<option value="'.$i.'" '.($c['color']==$i?'selected':'').'>'.$n.'</option>'; ?></select></label><label>Order on homepage<input name="sort" type="number" value="<?=e($c['sort'])?>"></label><label class="chk"><input type="checkbox" name="active" <?=$c['active']?'checked':''?>> Show on the site</label></div>
 <label>Products, one per line (exact product name or SKU). The first four show as pictures on the homepage slide.<textarea name="items" rows="10"><?=e(implode("\n",$ln))?></textarea></label><button class="btn">Save collection</button> <a href="collections.php">Cancel</a><?php if($c['id']): ?> <button class="btn ghost" name="del" value="1" onclick="return confirm('Delete this collection?')">Delete</button><?php endif; ?></form><?php afoot();exit;}
ahead('Collections','collections.php');$n=$db->query('SELECT COUNT(*) FROM collections')->fetchColumn();?><?=isset($_GET['ok'])?'<p class="okm">Saved</p>':''?><?=isset($_GET['miss'])?'<p class="bad">Not found, so skipped: '.e($_GET['miss']).'</p>':''?>
<p>Collections appear as a slideshow on the homepage. To feature single products in the other slideshow, tick "Feature this product" when editing a product (starred products below).</p><p><a class="btn" href="?edit=0">+ Add collection</a><?php if(!$n): ?> <form method="post" style="display:inline"><?=csrf()?><button class="btn ghost" name="seed" value="1">Create 4 starter collections and featured products</button></form><?php endif; ?></p>
<table class="tb"><tr><th>Collection</th><th>Products</th><th>Status</th></tr><?php foreach($db->query('SELECT c.*,(SELECT COUNT(*) FROM collection_items WHERE collection_id=c.id) n FROM collections c ORDER BY sort,id') as $c): ?><tr><td><a href="?edit=<?=$c['id']?>"><?=e($c['title'])?></a><br><small class="mut"><?=e($c['subtitle'])?></small></td><td><?=$c['n']?></td><td><?=badge($c['active']?'completed':'cancelled',$c['active']?'Live':'Hidden')?></td></tr><?php endforeach; ?></table>
<p class="mut">Featured products right now: <?=$db->query('SELECT COUNT(*) FROM products WHERE featured=1')->fetchColumn()?> (if none are starred, the homepage shows a selection of in-stock products).</p><?php afoot();
